    Rose = Color3.fromRGB(245, 115, 160),
}
local accent = themes.Purple
local textColor = Color3.fromRGB(239, 237, 247)
local muted = Color3.fromRGB(169, 163, 188)
local surface = Color3.fromRGB(35, 32, 49)
local accentBindings = {}

local function connect(signal, callback)
    local connection = signal:Connect(callback)
    table.insert(connections, connection)
    return connection
end

local function new(class, properties, parent)
    local object = Instance.new(class)
    for key, value in pairs(properties or {}) do object[key] = value end
    object.Parent = parent
    return object
end

local function round(object, radius)
    new("UICorner", { CornerRadius = UDim.new(0, radius or 10) }, object)
end

local function colored(object, property)
    object[property] = accent
    table.insert(accentBindings, { object, property })
    return object
end

local function notify(message)
    notification = tostring(message)
    notificationUntil = os.clock() + 5
    if footer then footer.Text = notification end
    if toast then toast.Text = notification; toast.Visible = true end
end

local function guarded(callback)
    return function(...)
        if not alive then return end
        local ok, err = pcall(callback, ...)
        if not ok then notify("Error: " .. tostring(err):sub(1, 160)) end
    end
end

local function sync(key)
    for _, update in ipairs(widgets[key] or {}) do update() end
end

local function watch(key, update)
    widgets[key] = widgets[key] or {}
    table.insert(widgets[key], update)
    update()
end

-- Layered overrides keep overlapping features independent.
local properties = setmetatable({}, { __mode = "k" })
local function applyProperty(object, property, cell)
    local chosen, priority = cell.base, -math.huge
    for _, layer in pairs(cell.layers) do
        if layer.priority > priority then
            chosen, priority = layer.value, layer.priority
        end
    end
    if object[property] ~= chosen then object[property] = chosen end
end

local function put(owner, object, property, value, priority)
    if not object then return end
    local list = properties[object]
    if not list then list = {}; properties[object] = list end
    local cell = list[property]
    if not cell then
        cell = { base = object[property], layers = {} }
        list[property] = cell
    end
    cell.layers[owner] = { value = value, priority = priority or 10 }
    applyProperty(object, property, cell)
end

local function release(owner)
    for object, list in pairs(properties) do
        for property, cell in pairs(list) do
            if cell.layers[owner] then
                cell.layers[owner] = nil
                pcall(applyProperty, object, property, cell)
                if next(cell.layers) == nil then list[property] = nil end
            end
        end
        if next(list) == nil then properties[object] = nil end
    end
end

local function restoreAll()
    for object, list in pairs(properties) do
        for property, cell in pairs(list) do
            pcall(function() object[property] = cell.base end)
        end
    end
    table.clear(properties)
end

local function define(key, enable, disable)
    features[key] = { enable = enable, disable = disable }
end

local function setFeature(key, enabled)
    local feature = features[key]
    if not feature then return end
    if values[key] == enabled then sync(key); return end
    values[key] = enabled
    local ok, err = pcall(function()
        if enabled then
            feature.enable()
        else
            if feature.disable then feature.disable() end
            release(key)
        end
    end)
    if not ok then
        values[key] = false
        if feature.disable then pcall(feature.disable) end
        release(key)
        notify(key .. ": " .. tostring(err):sub(1, 130))
    end
    sync(key)
end

local function refreshFeature(key)
    if values[key] and features[key] then features[key].enable() end
end

local function liveRoot()
    return root and root.Parent and humanoid and humanoid.Health > 0
end

local function applySpeed()
    if humanoid then put("speed", humanoid, "WalkSpeed", values.walkSpeed) end
end

local function applyJump()
    if not humanoid then return end
    put("jump", humanoid, "JumpPower", values.jumpPower)
    put("jump", humanoid, "JumpHeight", values.jumpPower ^ 2 / (2 * math.max(workspace.Gravity, 1)))
end

local function stopFlight()
    upHeld, downHeld = false, false
    table.clear(pointerHolds)
    if not activeFlight then release("fly"); return end
    local old = activeFlight
    activeFlight = nil
    old.velocity:Destroy()
    old.orientation:Destroy()
    old.attachment:Destroy()
    release("fly")
    if old.root.Parent then
        old.root.AssemblyLinearVelocity = Vector3.zero
        old.root.AssemblyAngularVelocity = Vector3.zero
    end
    if old.humanoid.Parent and old.humanoid.Health > 0 and not old.humanoid.PlatformStand then
        old.humanoid:ChangeState(Enum.HumanoidStateType.GettingUp)
    end
end

local flightPad
local function startFlight()
    if activeFlight or not liveRoot() then return end
    assert(not humanoid.Sit, "Keluar dari kursi/kendaraan terlebih dahulu")
    local attachment = new("Attachment", { Name = "NebulaFlight" }, root)
    local velocity = new("LinearVelocity", {
        Attachment0 = attachment, RelativeTo = Enum.ActuatorRelativeTo.World,
        MaxForce = math.huge, VectorVelocity = Vector3.zero,
    }, root)
    local orientation = new("AlignOrientation", {
        Attachment0 = attachment, Mode = Enum.OrientationAlignmentMode.OneAttachment,
        MaxTorque = math.huge, Responsiveness = 18, CFrame = root.CFrame.Rotation,
    }, root)
    activeFlight = {
        attachment = attachment, velocity = velocity, orientation = orientation,
        humanoid = humanoid, root = root,
    }
    put("fly", humanoid, "AutoRotate", false)
    put("fly", humanoid, "PlatformStand", true)
end

