local effectFolder = new("Folder", { Name = "NebulaUltraLocalEffects" }, workspace)
local playerEffects = {}
local function clearPlayerEffects(kind)
    for other, effects in pairs(playerEffects) do
        if effects[kind] then effects[kind]:Destroy(); effects[kind] = nil end
        if kind == "tag" then effects.caption = nil end
        if not effects.highlight and not effects.tag then playerEffects[other] = nil end
    end
end

local function updatePlayers()
    local present = {}
    for _, other in ipairs(Players:GetPlayers()) do
        if other ~= player then
            present[other] = true
            local model = other.Character
            local target = model and model:FindFirstChild("HumanoidRootPart")
            local head = model and (model:FindFirstChild("Head") or target)
            local effects = playerEffects[other] or {}
            playerEffects[other] = effects
            if effects.model ~= model then
                if effects.highlight then effects.highlight:Destroy() end
                if effects.tag then effects.tag:Destroy() end
                effects.highlight, effects.tag, effects.caption = nil, nil, nil
                effects.model = model
            end
            if effects.tag and effects.tag.Adornee ~= head then
                effects.tag:Destroy()
                effects.tag, effects.caption = nil, nil
            end
            local color = other.Team and other.TeamColor.Color or accent
            if values.highlights and model and not effects.highlight then
                effects.highlight = new("Highlight", {
                    Adornee = model, DepthMode = Enum.HighlightDepthMode.AlwaysOnTop,
                    FillTransparency = 0.8, OutlineTransparency = 0.1,
                }, effectFolder)
            end
            if effects.highlight then
                effects.highlight.FillColor, effects.highlight.OutlineColor = color, color
            end
            if values.nameplates and head and not effects.tag then
                effects.tag = new("BillboardGui", {
                    Adornee = head, AlwaysOnTop = true,
                    Size = UDim2.fromOffset(180, 42), MaxDistance = 1500,
                    StudsOffsetWorldSpace = Vector3.new(0, 3, 0),
                }, effectFolder)
                effects.caption = new("TextLabel", {
                    Size = UDim2.fromScale(1, 1), BackgroundTransparency = 1,
                    Font = Enum.Font.GothamBold, TextSize = 12,
                    TextStrokeTransparency = 0.3, TextColor3 = color,
                }, effects.tag)
            end
            if effects.caption then
                local distance = root and target and math.floor((root.Position - target.Position).Magnitude)
                effects.caption.Text = other.DisplayName .. "\n" .. (distance and distance .. " studs" or "...")
                effects.caption.TextColor3 = color
            end
        end
    end
    for other, effects in pairs(playerEffects) do
        if not present[other] then
            if effects.highlight then effects.highlight:Destroy() end
            if effects.tag then effects.tag:Destroy() end
            playerEffects[other] = nil
        end
    end
end
define("highlights", updatePlayers, function() clearPlayerEffects("highlight") end)
define("nameplates", updatePlayers, function() clearPlayerEffects("tag") end)

