local function filterRows()
    for i = #rows, 1, -1 do
        local row = rows[i]
        if not row.object.Parent then
            table.remove(rows, i)
        else
            row.object.Visible = query == "" or row.keywords:find(query, 1, true) ~= nil
        end
    end
end

local function page(name)
    local body = new("ScrollingFrame", {
        Position = UDim2.fromOffset(144, 126), Size = UDim2.new(1, -160, 1, -178),
        BackgroundTransparency = 1, BorderSizePixel = 0,
        ScrollBarThickness = 3, CanvasSize = UDim2.new(),
        AutomaticCanvasSize = Enum.AutomaticSize.Y,
        ScrollingDirection = Enum.ScrollingDirection.Y, Visible = name == currentTab,
    }, panel)
    colored(body, "ScrollBarImageColor3")
    new("UIListLayout", { Padding = UDim.new(0, 8), SortOrder = Enum.SortOrder.LayoutOrder }, body)
    new("UIPadding", { PaddingRight = UDim.new(0, 7), PaddingBottom = UDim.new(0, 8) }, body)
    local tab = button(sidebar, name, UDim2.new(1, 0, 0, 40))
    tab.LayoutOrder = #tabs + 1
    local record = { name = name, body = body, button = tab, order = 0 }
    table.insert(tabs, record)
    connect(tab.Activated, function()
        currentTab = name
        for _, item in ipairs(tabs) do
            item.body.Visible = item.name == name
            item.button.BackgroundColor3 = item.name == name and accent:Lerp(surface, 0.55) or surface
        end
    end)
    return record
end

local function row(pageRecord, height, keywords)
