local function toggle(pageRecord, title, key)
    local object = row(pageRecord, 44, title)
    local control = button(object, "", UDim2.fromScale(1, 1))
    text(control, title, UDim2.new(1, -86, 1, 0), UDim2.fromOffset(12, 0), 12)
    local status = text(control, "", UDim2.fromOffset(55, 26), UDim2.new(1, -67, 0, 9), 11)
    status.TextXAlignment = Enum.TextXAlignment.Center
    status.BackgroundTransparency = 0
    round(status, 7)
    watch(key, function()
        status.Text = values[key] and "ON" or "OFF"
        status.BackgroundColor3 = values[key] and accent:Lerp(surface, 0.3) or Color3.fromRGB(52, 47, 69)
    end)
    connect(control.Activated, guarded(function()
        if features[key] then setFeature(key, not values[key])
        else values[key] = not values[key]; sync(key) end
    end))
end

local activeSlider
local function slider(pageRecord, title, key, onChange)
    local limits = bounds[key]
    local minimum, maximum, step = limits[1], limits[2], limits[3]
    local object = row(pageRecord, 70, title)
    local caption = text(object, "", UDim2.new(1, -24, 0, 26), UDim2.fromOffset(12, 2), 12)
    local minus = button(object, "−", UDim2.fromOffset(28, 28), UDim2.fromOffset(9, 34))
    local plus = button(object, "+", UDim2.fromOffset(28, 28), UDim2.new(1, -37, 0, 34))
    local track = button(object, "", UDim2.new(1, -94, 0, 28), UDim2.fromOffset(47, 34))
    track.BackgroundTransparency = 1
    local rail = new("Frame", {
        Position = UDim2.new(0, 0, 0.5, -3), Size = UDim2.new(1, 0, 0, 6),
        BackgroundColor3 = Color3.fromRGB(61, 53, 80), BorderSizePixel = 0,
    }, track)
    round(rail, 3)
    local fill = colored(new("Frame", {
        Size = UDim2.fromScale(0, 1), BorderSizePixel = 0,
    }, rail), "BackgroundColor3")
    round(fill, 3)
    watch(key, function()
        caption.Text = title .. "  ·  " .. string.format(step < 1 and "%.2f" or "%d", values[key])
        fill.Size = UDim2.fromScale((values[key] - minimum) / (maximum - minimum), 1)
    end)
    local function set(value)
        values[key] = math.clamp(math.round(value / step) * step, minimum, maximum)
        sync(key)
        if onChange then onChange() end
    end
    local function at(x)
        local ratio = (x - track.AbsolutePosition.X) / math.max(track.AbsoluteSize.X, 1)
        set(minimum + math.clamp(ratio, 0, 1) * (maximum - minimum))
    end
    connect(minus.Activated, guarded(function() set(values[key] - step) end))
    connect(plus.Activated, guarded(function() set(values[key] + step) end))
    connect(track.InputBegan, function(input)
        if input.UserInputType == Enum.UserInputType.MouseButton1 or input.UserInputType == Enum.UserInputType.Touch then
            activeSlider = { input = input, at = guarded(at) }
            activeSlider.at(input.Position.X)
        end
    end)
end

