local function fitPanel()
    local camera = workspace.CurrentCamera
    if not camera then return end
    local viewport = camera.ViewportSize
    if viewport.X < 48 or viewport.Y < 72 then return end
    local compact = viewport.X < 560 and viewport.Y > viewport.X
    local width, height = compact and 400 or 680, compact and 620 or 530
    panel.Size = UDim2.fromOffset(width, height)
    sidebar.Size = compact and UDim2.new(1, -32, 0, 40) or UDim2.new(0, 112, 1, -132)
    sidebar.AutomaticCanvasSize = compact and Enum.AutomaticSize.X or Enum.AutomaticSize.Y
    sidebar.ScrollingDirection = compact and Enum.ScrollingDirection.X or Enum.ScrollingDirection.Y
    tabLayout.FillDirection = compact and Enum.FillDirection.Horizontal or Enum.FillDirection.Vertical
    for _, item in ipairs(tabs) do
        item.button.Size = compact and UDim2.fromOffset(88, 40) or UDim2.new(1, 0, 0, 40)
        item.button.TextSize = 12
        item.body.Position = compact and UDim2.fromOffset(16, 170) or UDim2.fromOffset(144, 126)
        item.body.Size = compact and UDim2.new(1, -32, 1, -222) or UDim2.new(1, -160, 1, -178)
    end
    search.Position = compact and UDim2.fromOffset(16, 128) or UDim2.fromOffset(144, 82)
    search.Size = compact and UDim2.new(1, -32, 0, 34) or UDim2.new(1, -160, 0, 34)
    scaleObject.Scale = math.min(values.uiScale, (viewport.X - 24) / width, (viewport.Y - 48) / height)
    local halfW, halfH = width * scaleObject.Scale / 2, height * scaleObject.Scale / 2
    local x = panel.Position.X.Scale * viewport.X + panel.Position.X.Offset
    local y = panel.Position.Y.Scale * viewport.Y + panel.Position.Y.Offset
    panel.Position = UDim2.fromOffset(math.clamp(x, halfW, viewport.X - halfW), math.clamp(y, halfH, viewport.Y - halfH))
end

