local function clearPlayerRows()
    for _, connection in ipairs(playerRowConnections) do connection:Disconnect() end
    table.clear(playerRowConnections)
    for _, object in ipairs(playerRows) do object:Destroy() end
    table.clear(playerRows)
end
local function rebuildPlayerList()
    clearPlayerRows()
    local others = Players:GetPlayers()
    table.sort(others, function(a, b) return a.Name:lower() < b.Name:lower() end)
    for _, other in ipairs(others) do
        if other ~= player then
            local title = other.DisplayName .. "  (@" .. other.Name .. ")"
            local object = row(playersPage, 42, title)
            local control = button(object, title, UDim2.fromScale(1, 1))
            local connection = control.Activated:Connect(guarded(function()
                selectedPlayer = other
                if values.spectate then refreshFeature("spectate") end
                notify("Dipilih: @" .. other.Name)
            end))
            table.insert(playerRowConnections, connection)
            table.insert(playerRows, object)
        end
    end
    filterRows()
end

