-- Validate imported JSON against a whitelist; never execute profile content.
local function sanitize(raw)
    assert(type(raw) == "table", "Profile harus berupa objek JSON")
    local clean = table.clone(defaults)
    for key, default in pairs(defaults) do
        local value = raw[key]
        if type(value) == type(default) then
            if type(default) == "number" then
                if value == value and math.abs(value) < math.huge then
                    local limit = bounds[key]
                    clean[key] = math.clamp(math.round(value / limit[3]) * limit[3], limit[1], limit[2])
                end
            elseif key == "theme" then
                if themes[value] then clean[key] = value end
            else clean[key] = value end
        end
    end
    return clean
end

local function applyProfile(raw)
    local clean = sanitize(raw)
    for key in pairs(features) do setFeature(key, false) end
    for key, value in pairs(clean) do if not features[key] then values[key] = value end end
    for key in pairs(features) do if clean[key] then setFeature(key, true) end end
    for key in pairs(widgets) do sync(key) end
    fitPanel()
    applyTheme()
end

local function fileFunction(name)
    local fn = env[name]
    assert(type(fn) == "function", "Executor tidak menyediakan " .. name .. "; gunakan session profile")
    return fn
end
