connect(header.InputBegan, function(input)
    if input.UserInputType == Enum.UserInputType.Touch or input.UserInputType == Enum.UserInputType.MouseButton1 then
        drag = { input = input, position = panel.Position, origin = input.Position }
    end
end)
local function matches(input, start)
    return input == start or (start.UserInputType == Enum.UserInputType.MouseButton1
        and input.UserInputType == Enum.UserInputType.MouseMovement)
end
connect(Input.InputChanged, function(input)
    if activeSlider and matches(input, activeSlider.input) then activeSlider.at(input.Position.X)
    elseif drag and matches(input, drag.input) then
        local delta = input.Position - drag.origin
        panel.Position = UDim2.new(drag.position.X.Scale, drag.position.X.Offset + delta.X,
            drag.position.Y.Scale, drag.position.Y.Offset + delta.Y)
    end
end)
connect(Input.InputEnded, function(input)
    if activeSlider and input == activeSlider.input then activeSlider = nil end
    if drag and input == drag.input then drag = nil; fitPanel() end
    pointerHolds[input] = nil
    upHeld, downHeld = false, false
    for _, direction in pairs(pointerHolds) do
        if direction == "up" then upHeld = true else downHeld = true end
    end
end)
connect(Input.InputBegan, function(input, processed)
    if not processed and not Input:GetFocusedTextBox() and input.KeyCode == Enum.KeyCode.RightShift then
        setVisible(not panel.Visible)
    end
end)
connect(Input.WindowFocusReleased, function()
    focused, drag, activeSlider = false, nil, nil
    upHeld, downHeld = false, false
