local frames, elapsed, refreshElapsed, fps = 0, 0, 0, 0
local viewport = Vector2.zero
local function flightStep()
    if not activeFlight then return end
    if not values.fly or not liveRoot() then stopFlight(); return end
    local camera = workspace.CurrentCamera
    if not camera then activeFlight.velocity.VectorVelocity = Vector3.zero; return end
    local direction = humanoid.MoveDirection
    if focused and not Input:GetFocusedTextBox() then
        local x, z = 0, 0
        if Input:IsKeyDown(Enum.KeyCode.D) then x = x + 1 end
        if Input:IsKeyDown(Enum.KeyCode.A) then x = x - 1 end
        if Input:IsKeyDown(Enum.KeyCode.W) then z = z + 1 end
        if Input:IsKeyDown(Enum.KeyCode.S) then z = z - 1 end
        if x ~= 0 or z ~= 0 then direction = camera.CFrame.RightVector * x + camera.CFrame.LookVector * z end
        local rise, fall = upHeld and 1 or 0, downHeld and 1 or 0
        if Input:IsKeyDown(Enum.KeyCode.Space) then rise = 1 end
        if Input:IsKeyDown(Enum.KeyCode.LeftControl) or Input:IsKeyDown(Enum.KeyCode.RightControl) then fall = 1 end
        direction = direction + Vector3.yAxis * (rise - fall)
    else direction = Vector3.zero end
    if direction.Magnitude > 1 then direction = direction.Unit end
    activeFlight.velocity.VectorVelocity = direction * values.flySpeed
    local look = camera.CFrame.LookVector
    local flat = Vector3.new(look.X, 0, look.Z)
    if flat.Magnitude > 0.001 then activeFlight.orientation.CFrame = CFrame.lookAt(Vector3.zero, flat) end
end

connect(Run.RenderStepped, function(dt)
    flightStep()
    local camera = workspace.CurrentCamera
    if camera and camera.ViewportSize ~= viewport then viewport = camera.ViewportSize; fitPanel() end
    frames, elapsed, refreshElapsed = frames + 1, elapsed + dt, refreshElapsed + dt
    if elapsed >= 0.5 then fps = math.floor(frames / elapsed + 0.5); frames, elapsed = 0, 0 end
    if refreshElapsed < 0.5 then return end
    refreshElapsed = 0
    if values.highlights or values.nameplates or next(playerEffects) then updatePlayers() end
    if values.noBlur then removeBlur() end
    if values.invisibleSelf then hideSelf() end
    if values.spectate then pcall(spectate) end
    if selectedPlayer then
        local model = selectedPlayer.Character
        local h = model and model:FindFirstChildOfClass("Humanoid")
        selectedInfo.Text = "@" .. selectedPlayer.Name .. " | HP " .. (h and math.floor(h.Health) or "-")
    else selectedInfo.Text = "Belum ada pemain dipilih. Daftar pemain ada di bawah." end
    if os.clock() >= notificationUntil then
        toast.Visible = false
        if values.stats and liveRoot() then
            local ping = "-"
            pcall(function() ping = tostring(math.floor(Stats.Network.ServerStatsItem["Data Ping"]:GetValue())) end)
            local p = root.Position
            footer.Text = string.format("%d FPS | %s ms | HP %.0f | XYZ %.0f / %.0f / %.0f", fps, ping, humanoid.Health, p.X, p.Y, p.Z)
        else footer.Text = "NEBULA 50000 | RightShift = buka/tutup | × = unload" end
    end
end)

-- Upgrade module: runs in the same lexical scope as the base panel.
local Pathfinding = game:GetService("PathfindingService")
local startedAt = os.clock()
local totalFrames, totalSeconds, traveled, maxSpeed = 0, 0, 0, 0
local lastMeasuredPosition, lastSafePosition
local routeGeneration, activeRoute = 0, false
local routeControls
local cameraMode, gradeEffect, airPlatform
local recordedPath, playingPath = {}, nil
local recordStarted, recordElapsed = nil, 0
local selectedPreset = 1
local cameraSavedViews = {}
local internalChanges = false
local library = NEBULA_PRESETS

local function positionOf(model)
    return model and model:FindFirstChild("HumanoidRootPart")
end

local function stopRoute()
    routeGeneration = routeGeneration + 1
    activeRoute = false
    if humanoid and root then humanoid:MoveTo(root.Position) end
    if routeControls then
        if routeControls.wasEnabled then pcall(function() routeControls.controls:Enable() end) end
        routeControls = nil
    end
end

local function finishRoute(ticket)
    if ticket ~= routeGeneration then return end
    activeRoute = false
    if routeControls and routeControls.ticket == ticket then
        local owned = routeControls
        routeControls = nil
        if owned.wasEnabled then pcall(function() owned.controls:Enable() end) end
    end
end

local function beginRoute(destination)
    assert(liveRoot(), "Karakter belum siap")
    assert(not values.fly and not values.freezeSelf, "Matikan flight/freeze sebelum navigasi")
    stopRoute()
    local ticket, movingHumanoid, movingRoot = routeGeneration, humanoid, root
    local scripts = player:FindFirstChild("PlayerScripts")
    local module = scripts and scripts:FindFirstChild("PlayerModule")
    assert(module and module:IsA("ModuleScript"), "Kontrol PlayerModule tidak tersedia; navigasi dibatalkan")
    local okControls, controls = pcall(function() return require(module):GetControls() end)
    assert(okControls and type(controls) == "table" and type(controls.controlsEnabled) == "boolean"
        and type(controls.Disable) == "function" and type(controls.Enable) == "function",
        "Kontrol default tidak dikenali; navigasi dibatalkan")
    routeControls = { controls = controls, wasEnabled = controls.controlsEnabled, ticket = ticket }
    if routeControls.wasEnabled then
        local disabled, failure = pcall(function() controls:Disable() end)
        if not disabled then finishRoute(ticket); error(tostring(failure)) end
    end
    activeRoute = true
    notify("Menghitung jalur menuju bookmark...")
    task.spawn(function()
        local created, path = pcall(function() return Pathfinding:CreatePath({
            AgentRadius = 2,
            AgentHeight = 5,
            AgentCanJump = true,
            WaypointSpacing = 4,
        }) end)
        if not created then finishRoute(ticket); notify("Pathfinding gagal: " .. tostring(path)); return end
        local ok, err = pcall(function() path:ComputeAsync(movingRoot.Position, destination) end)
        if not alive or ticket ~= routeGeneration then path:Destroy(); return end
        if not ok or path.Status ~= Enum.PathStatus.Success then
            finishRoute(ticket)
            path:Destroy()
            notify("Jalur tidak ditemukan: " .. tostring(err or "area terhalang"))
            return
        end
        local blocked = false
        local currentWaypoint = 1
        local blockedConnection = path.Blocked:Connect(function(index)
            if index >= currentWaypoint then blocked = true end
        end)
        local success, failure = pcall(function()
            for index, waypoint in ipairs(path:GetWaypoints()) do
                currentWaypoint = index
                if not alive or ticket ~= routeGeneration or blocked or movingHumanoid.Health <= 0 then break end
                if waypoint.Action == Enum.PathWaypointAction.Jump then movingHumanoid.Jump = true end
                movingHumanoid:MoveTo(waypoint.Position)
                local timeout = os.clock() + 8
                repeat
                    task.wait(0.05)
                until not alive or ticket ~= routeGeneration or blocked
                    or movingHumanoid.Health <= 0 or not movingRoot.Parent
                    or (movingRoot.Position - waypoint.Position).Magnitude <= 4
                    or os.clock() >= timeout
                if not movingRoot.Parent or os.clock() >= timeout then
                    error("Waypoint tidak tercapai sebelum batas waktu")
                end
            end
        end)
        blockedConnection:Disconnect()
        path:Destroy()
        if not alive or ticket ~= routeGeneration then return end
        finishRoute(ticket)
        if blocked then notify("Jalur berubah/terhalang. Jalankan navigasi lagi.")
        elseif not success then notify("Navigasi berhenti: " .. tostring(failure))
        elseif movingHumanoid.Health <= 0 then notify("Navigasi berhenti: karakter mati.")
        else notify("Navigasi selesai.") end
    end)
end

local rayParameters = RaycastParams.new()
rayParameters.FilterType = Enum.RaycastFilterType.Exclude
local function castFrom(origin, direction)
    local excluded = { effectFolder }
    if character then table.insert(excluded, character) end
    rayParameters.FilterDescendantsInstances = excluded
    return workspace:Raycast(origin, direction, rayParameters)
end

