local gradeDefinitions = {
    Neutral = { 0, 0, 0, Color3.new(1, 1, 1) },
    Filmic = { 0, 0.18, -0.12, Color3.fromRGB(255, 238, 220) },
    Mono = { 0, 0.12, -1, Color3.new(1, 1, 1) },
    Warm = { 0.03, 0.04, 0.05, Color3.fromRGB(255, 225, 195) },
    Cool = { 0.02, 0.07, -0.05, Color3.fromRGB(205, 230, 255) },
    Soft = { 0.04, -0.12, -0.1, Color3.fromRGB(250, 235, 255) },
}
local function applyGrade()
    local grade = gradeDefinitions[values.colorGrade] or gradeDefinitions.Neutral
    if not gradeEffect then gradeEffect = new("ColorCorrectionEffect", { Name = "NebulaColorGrade" }, Lighting) end
    gradeEffect.Brightness, gradeEffect.Contrast, gradeEffect.Saturation, gradeEffect.TintColor = table.unpack(grade)
end
