    if gradeEffect then gradeEffect:Destroy(); gradeEffect = nil end
end)

local function stopCamera()
    cameraMode = nil
    playingPath = nil
    release("freecam")
    release("orbit")
    release("pathPlayback")
    release("freecamPointer")
    local camera = workspace.CurrentCamera
    if camera and humanoid and (not camera.CameraSubject or not camera.CameraSubject.Parent) then
        camera.CameraSubject = humanoid
    end
end

local function stopCameraMode(owner)
    if cameraMode and cameraMode.mode == owner then stopCamera()
    else release(owner) end
end

local function cameraConflict(except)
    internalChanges = true
    for _, key in ipairs({ "freecam", "orbit", "pathPlayback", "spectate" }) do
        if key ~= except and values[key] then setFeature(key, false) end
    end
    internalChanges = false
end

