    assert(liveRoot() and not values.freezeSelf, "Karakter belum siap atau sedang freeze")
    local forward = root.CFrame.LookVector
    local flat = Vector3.new(forward.X, 0, forward.Z)
    if flat.Magnitude > 0 then root.AssemblyLinearVelocity = flat.Unit * values.dashSpeed + Vector3.yAxis * root.AssemblyLinearVelocity.Y end
end)

