local function freeCameraStep(dt)
    local camera = workspace.CurrentCamera
    if not cameraMode or not camera then return end
    if cameraMode.mode == "freecam" then
        local movement = Vector3.zero
        if focused and not Input:GetFocusedTextBox() then
            local x, y, z = 0, 0, 0
            if Input:IsKeyDown(Enum.KeyCode.D) then x = x + 1 end
            if Input:IsKeyDown(Enum.KeyCode.A) then x = x - 1 end
            if Input:IsKeyDown(Enum.KeyCode.E) or upHeld then y = y + 1 end
            if Input:IsKeyDown(Enum.KeyCode.Q) or downHeld then y = y - 1 end
            if Input:IsKeyDown(Enum.KeyCode.W) then z = z - 1 end
            if Input:IsKeyDown(Enum.KeyCode.S) then z = z + 1 end
            if Input:IsMouseButtonPressed(Enum.UserInputType.MouseButton2) then
                put("freecamPointer", Input, "MouseBehavior", Enum.MouseBehavior.LockCurrentPosition)
                local delta = Input:GetMouseDelta()
                cameraMode.yaw = cameraMode.yaw - delta.X * values.cameraSensitivity * 0.002
                cameraMode.pitch = math.clamp(cameraMode.pitch - delta.Y * values.cameraSensitivity * 0.002, -1.5, 1.5)
            else release("freecamPointer") end
            local rotation = CFrame.fromOrientation(cameraMode.pitch, cameraMode.yaw, 0)
            movement = rotation:VectorToWorldSpace(Vector3.new(x, y, z))
            if Input.TouchEnabled and humanoid then movement = movement + humanoid.MoveDirection end
            if movement.Magnitude > 1 then movement = movement.Unit end
            cameraMode.frame = CFrame.new(cameraMode.frame.Position + movement * values.freecamSpeed * dt) * rotation
        end
        if not focused or Input:GetFocusedTextBox() then release("freecamPointer") end
        put("freecam", camera, "CFrame", cameraMode.frame, 30)
    elseif cameraMode.mode == "orbit" then
        local target = selectedPlayer and positionOf(selectedPlayer.Character)
        if not target then return end
        cameraMode.angle = cameraMode.angle + math.rad(values.orbitSpeed) * dt
        local offset = Vector3.new(math.cos(cameraMode.angle) * values.orbitRadius, values.orbitHeight, math.sin(cameraMode.angle) * values.orbitRadius)
        put("orbit", camera, "CFrame", CFrame.lookAt(target.Position + offset, target.Position), 30)
    elseif cameraMode.mode == "pathPlayback" and playingPath then
        if #recordedPath < 2 then setFeature("pathPlayback", false); return end
        local time = os.clock() - playingPath.started
        local last = recordedPath[#recordedPath]
        if time >= last.time then
            if values.loopCamera then playingPath.started, playingPath.index = os.clock(), 1; time = 0
            else setFeature("pathPlayback", false); return end
        end
        local index = playingPath.index
        while index < #recordedPath - 1 and recordedPath[index + 1].time < time do index = index + 1 end
        playingPath.index = index
        local first, second = recordedPath[index], recordedPath[index + 1]
        local alpha = math.clamp((time - first.time) / math.max(second.time - first.time, 0.001), 0, 1)
        put("pathPlayback", camera, "CFrame", first.frame:Lerp(second.frame, alpha), 30)
    end
end

local featureOwners = { "freezeSelf", "noAutoRotate", "alwaysSit" }
connect(player.CharacterRemoving, function()
    stopRoute()
    lastSafePosition, lastMeasuredPosition = nil, nil
    for _, owner in ipairs(featureOwners) do release(owner) end
end)
connect(player.CharacterAdded, function(model)
    task.spawn(function()
        local h = model:WaitForChild("Humanoid", 15)
        local r = model:WaitForChild("HumanoidRootPart", 15)
        if not alive or not h or not r or player.Character ~= model then return end
        local deadline = os.clock() + 20
        repeat task.wait() until not alive or player.Character ~= model or humanoid == h or os.clock() >= deadline
        if not alive or player.Character ~= model or humanoid ~= h then return end
        for _, owner in ipairs(featureOwners) do if values[owner] then pcall(features[owner].enable) end end
    end)
end)
connect(workspace:GetPropertyChangedSignal("CurrentCamera"), function()
    if cameraMode then
        local active = cameraMode.mode
        release(active)
        pcall(function() features[active].enable() end)
    end
end)
connect(Input.WindowFocusReleased, function() release("freecamPointer") end)

connect(Run.PreSimulation, function()
    if airPlatform and liveRoot() then
        local offset = humanoid.HipHeight + root.Size.Y / 2 + 0.3
        airPlatform.CFrame = CFrame.new(root.Position - Vector3.yAxis * offset)
    end
    if values.bunnyHop and liveRoot() and not values.fly and not values.freezeSelf and not humanoid.Sit
        and humanoid.MoveDirection.Magnitude > 0.1 and humanoid.FloorMaterial ~= Enum.Material.Air then
        humanoid.Jump = true
    end
end)

local sampleElapsed, paletteElapsed = 0, 0
connect(Run.RenderStepped, function(dt)
    totalFrames, totalSeconds = totalFrames + 1, totalSeconds + dt
    if cameraMode then freeCameraStep(dt) end
    flightPad.Visible = values.fly or values.freecam
    hud.Visible = values.floatingHUD
    if recordStarted and workspace.CurrentCamera then
        recordElapsed = recordElapsed + dt
        if recordElapsed >= 0.1 then
            recordElapsed = 0
            table.insert(recordedPath, { time = os.clock() - recordStarted, frame = workspace.CurrentCamera.CFrame })
            if os.clock() - recordStarted >= 60 then recordStarted = nil; notify("Rekaman kamera mencapai 60 detik.") end
        end
    end
    if liveRoot() then
        local speed = root.AssemblyLinearVelocity.Magnitude
        maxSpeed = math.max(maxSpeed, speed)
        if lastMeasuredPosition then
            local step = (root.Position - lastMeasuredPosition).Magnitude
            if step < 100 then traveled = traveled + step end
        end
        lastMeasuredPosition = root.Position
        if values.voidReturn and lastSafePosition and root.Position.Y < values.voidY then
            root.CFrame = lastSafePosition
            root.AssemblyLinearVelocity = Vector3.zero
        end
    end
    sampleElapsed, paletteElapsed = sampleElapsed + dt, paletteElapsed + dt
    if sampleElapsed < 0.25 then return end
    sampleElapsed = 0
    if liveRoot() then
        local ground = castFrom(root.Position, Vector3.new(0, -12, 0))
        if ground and humanoid.FloorMaterial ~= Enum.Material.Air then lastSafePosition = root.CFrame end
        local speed = root.AssemblyLinearVelocity.Magnitude
        speedLabel.Text = string.format("SPEED %.1f studs/s | MAX %.1f", speed, maxSpeed)
        healthFill.Size = UDim2.fromScale(math.clamp(humanoid.Health / math.max(humanoid.MaxHealth, 1), 0, 1), 1)
        healthLabel.Text = string.format("HP %.0f / %.0f", humanoid.Health, humanoid.MaxHealth)
    end
    local camera = workspace.CurrentCamera
    if camera then
        local look = camera.CFrame.LookVector
        local headingDegrees = (math.deg(math.atan2(look.X, -look.Z)) + 360) % 360
        local labels = { "N", "NE", "E", "SE", "S", "SW", "W", "NW" }
        compass.Text = string.format("%s  |  %.0f°", labels[math.floor((headingDegrees + 22.5) / 45) % 8 + 1], headingDegrees)
        arrow.Visible = values.directionArrow and savedPlaces[1] ~= nil and root ~= nil
        if arrow.Visible then
            local relative = camera.CFrame:VectorToObjectSpace(savedPlaces[1].Position - root.Position)
            arrow.Rotation = math.deg(math.atan2(relative.X, -relative.Z))
        end
    end
    compass.Visible, speedLabel.Visible = values.compass, values.speedometer
    healthBackground.Visible, healthLabel.Visible = values.healthBar, values.healthBar
    sessionLabel.Visible = values.sessionStats
    sessionLabel.Text = string.format("%ds | %.0f studs | AVG %.0f FPS", math.floor(os.clock() - startedAt), traveled, totalFrames / math.max(totalSeconds, 0.001))
    if timerRunning and os.clock() >= timerEnd then timerRunning = false; notify("Timer selesai.") end
    refreshMarkers()
    if values.clearAtmosphere then clearAtmosphere() end
    if values.noBloom then features.noBloom.enable() end
    if values.rainbow and paletteElapsed >= 0.5 then
        paletteElapsed = 0
        accent = Color3.fromHSV((os.clock() % 12) / 12, 0.65, 1)
        for _, binding in ipairs(accentBindings) do if binding[1].Parent then binding[1][binding[2]] = accent end end
    end
    diagnosticLabel.Text = string.format("Route: %s | Camera frames: %d | Presets: %d | Runtime: %ds",
        activeRoute and "ACTIVE" or "IDLE", #recordedPath, #library, math.floor(os.clock() - startedAt))
end)

